17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
35	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
36	import org.springframework.security.access.AccessDeniedException;
37	import org.springframework.validation.BindingResult;
38	import org.springframework.validation.FieldError;
39	import org.springframework.web.bind.MethodArgumentNotValidException;
40	import org.springframework.web.bind.annotation.ControllerAdvice;
41	import org.springframework.web.bind.annotation.ExceptionHandler;
42	import org.springframework.web.bind.annotation.ResponseBody;
43	
44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone number already exists";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
81	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
82	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
83	     * would catch it and report an authorization failure as a 500.
84	     *
85	     * @param e The {@link AccessDeniedException} to propagate
86	     * @throws AccessDeniedException always
87	     */
88	    @ExceptionHandler(AccessDeniedException.class)
89	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
90	        throw e;
91	    }
92	
93	    /**
94	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
95	     *
96	     * @param e The {@link Exception} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
99	     */
100	    @ExceptionHandler(Exception.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
103	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
104	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
111	     * method returns a 404 Not Found status if an entity does not exist.
112	     *
113	     * @param e The {@link DataIntegrityViolationException} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
116	     */
117	    @ExceptionHandler(DataIntegrityViolationException.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
120	        logger.warn("Data integrity violation at {} {}: {}",
121	            request.getMethod(),
122	            request.getRequestURI(),
123	            e.getMessage());
124	        logger.debug("Data integrity violation stacktrace", e);
125	        HttpStatus status = HttpStatus.NOT_FOUND;
126	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
127	        return ResponseEntity.status(status).body(detail);
128	    }
129	
130	    /**
131	     * Handles exception thrown by Bean Validation on controller methods parameters
132	     *
133	     * @param e The {@link MethodArgumentNotValidException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
136	     */
137	    @ExceptionHandler(MethodArgumentNotValidException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
140	        HttpStatus status = HttpStatus.BAD_REQUEST;
141	        BindingErrorsResponse errors = new BindingErrorsResponse();
142	        BindingResult bindingResult = e.getBindingResult();
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
144	        if (bindingResult.hasErrors()) {
145	            errors.addAllErrors(bindingResult);
146	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
147	                .map(fieldError -> {
148	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
149	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
150	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
151	                        fieldError.getField(),
152	                        defaultMessage,
153	                        rejectedValue);
154	                    return new ValidationMessageDto(message)
155	                        .putAdditionalProperty("field", fieldError.getField())
156	                        .putAdditionalProperty("rejectedValue", rejectedValue)
157	                        .putAdditionalProperty("defaultMessage", defaultMessage);
158	                })
159	                .toList();
160	            logger.debug("Validation error at {} {}: {}",
161	                request.getMethod(),
162	                request.getRequestURI(),
163	                bindingResult.getFieldErrors());
164	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
165	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
166	                .map(FieldError::getField)
167	                .distinct()
168	                .toList();
169	            detail.setProperty("errors", invalidFields);
170	            return ResponseEntity.status(status).body(detail);
171	        }
172	        return ResponseEntity.status(status).body(detail);
173	    }
174	
175	    /**
176	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
177	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
178	     * the name of each missing field.
179	     *
180	     * @param e The {@link MissingOwnerFieldsException} to be handled
181	     * @param request {@link HttpServletRequest} object referring to the current request.
182	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
183	     */
184	    @ExceptionHandler(MissingOwnerFieldsException.class)
185	    @ResponseBody
186	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", e.getFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
195	     * converted to a valid E.164 value, returning a 400 Bad Request.
196	     *
197	     * @param e The {@link InvalidTelephoneException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(InvalidTelephoneException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
204	        HttpStatus status = HttpStatus.BAD_REQUEST;
205	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
206	        detail.setProperty("errors", List.of("telephone"));
207	        return ResponseEntity.status(status).body(detail);
208	    }
209	
210	    /**
211	     * Handles {@link DuplicateTelephoneException} raised when a new owner is submitted with a normalized
212	     * telephone number that is already used by an existing owner, returning a 409 Conflict.
213	     *
214	     * @param e The {@link DuplicateTelephoneException} to be handled
215	     * @param request {@link HttpServletRequest} object referring to the current request.
216	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
217	     */
218	    @ExceptionHandler(DuplicateTelephoneException.class)
219	    @ResponseBody
220	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
221	        HttpStatus status = HttpStatus.CONFLICT;
222	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
223	        detail.setProperty("errors", List.of("telephone"));
224	        return ResponseEntity.status(status).body(detail);
225	    }
226	
227	}
