17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.List;
20	
21	/**
22	 * Raised when a request to create or update an owner omits one or more mandatory fields.
23	 * The offending field names are reported so the client can be told exactly what is missing.
24	 */
25	public class MissingOwnerFieldsException extends RuntimeException {
26	
27	    private final List<String> fields;
28	
29	    public MissingOwnerFieldsException(List<String> fields) {
30	        super("Missing required owner fields: " + fields);
31	        this.fields = List.copyOf(fields);
32	    }
33	
34	    public List<String> getFields() {
35	        return this.fields;
36	    }
37	}
