18	
19	import java.util.regex.Pattern;
20	
21	/**
22	 * Normalizes an owner's telephone number to canonical E.164 form. A leading {@code '+'} and its
23	 * country code are preserved when present; otherwise the default country code {@code +61} is
24	 * assumed and a single leading {@code '0'} is dropped from the national digits. Separators such as
25	 * spaces, dashes and brackets are stripped. The result must carry 8 to 15 digits after the
26	 * {@code '+'}, and a number that cannot form a valid E.164 value is rejected.
27	 */
28	public final class TelephoneNormalizer {
29	
30	    private static final Pattern NON_DIGIT = Pattern.compile("\\D");
31	
32	    private static final String DEFAULT_COUNTRY_CODE = "+61";
33	
34	    private static final int MIN_DIGITS = 8;
35	
36	    private static final int MAX_DIGITS = 15;
37	
38	    private TelephoneNormalizer() {
39	    }
40	
41	    /**
42	     * Converts the supplied telephone to its canonical E.164 representation.
43	     *
44	     * @param telephone the raw telephone as submitted
45	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
46	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
47	     */
48	    public static String normalize(String telephone) {
49	        String trimmed = telephone == null ? "" : telephone.trim();
50	        boolean hasCountryCode = trimmed.startsWith("+");
51	        String digits = NON_DIGIT.matcher(trimmed).replaceAll("");
52	
53	        String national = digits;
54	        if (!hasCountryCode && national.startsWith("0")) {
55	            national = national.substring(1);
56	        }
57	        String prefix = hasCountryCode ? "+" : DEFAULT_COUNTRY_CODE;
58	        String e164 = prefix + national;
59	
60	        int digitCount = e164.length() - 1;
61	        if (digitCount < MIN_DIGITS || digitCount > MAX_DIGITS) {
62	            throw new InvalidTelephoneException(telephone);
63	        }
64	        return e164;
65	    }
66	}
